<script setup lang="ts">interface Props{modelValue:boolean;label?:string;disabled?:boolean}defineProps<Props>();defineEmits<{(e:'update:modelValue',v:boolean):void}>()</script><template><label class="inline-flex items-center gap-2"><input type="checkbox" :checked="modelValue" :disabled="disabled" @change="$emit('update:modelValue', ($event.target as HTMLInputElement).checked)"/><span>{{label}}</span></label></template>
